        "tags": [],
        "jsDoc": "/**\n * The taskboard service (ctx.taskboard): storage-backed tickets and boards,\n * the master seat, workflow transitions, the browser Remote surface, and the\n * model-facing tools.\n */",
        "key": "taskboard",
